#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\n简化的交互式演示流程测试\n\"\"\"\n\nimport asyncio\nimport sys\nimport os\n\n# 添加项目根目录到Python路径\nsys.path.append('.')\n\nfrom src.real_demo_system.interactive_demo_flow import InteractiveDemoFlow, DemoScenarioType\n\n\nasync def test_demo_flow():\n    \"\"\"测试演示流程\"\"\"\n    print(\"🚀 开始交互式演示流程测试\")\n    print(\"=\" * 60)\n    \n    # 创建演示流程实例\n    demo_flow = InteractiveDemoFlow()\n    \n    # 1. 测试场景初始化\n    print(\"\\n📋 测试场景初始化\")\n    scenarios = demo_flow.get_available_scenarios()\n    print(f\"✅ 成功初始化 {len(scenarios)} 个演示场景\")\n    \n    for scenario_type, info in scenarios.items():\n        print(f\"   - {info['name']} ({scenario_type})\")\n    \n    # 2. 测试演示启动\n    print(\"\\n🎬 测试演示启动\")\n    start_result = await demo_flow.start_demo(\n        DemoScenarioType.MULTI_ROLE_DEBATE.value,\n        {\"topic\": \"AI在教育中的应用\"}\n    )\n    \n    if \"error\" not in start_result:\n        print(f\"✅ 演示启动成功\")\n        print(f\"   演示ID: {start_result['demo_id']}\")\n        print(f\"   场景: {start_result['scenario_name']}\")\n        print(f\"   总步骤: {start_result['total_steps']}\")\n    else:\n        print(f\"❌ 演示启动失败: {start_result['error']}\")\n        return False\n    \n    # 3. 测试步骤执行\n    print(\"\\n⚡ 测试步骤执行\")\n    step_count = 0\n    max_steps = 3  # 只测试前3步\n    \n    while step_count < max_steps:\n        step_result = await demo_flow.execute_next_step({\n            \"user_input\": f\"测试输入 - 步骤 {step_count + 1}\"\n        })\n        \n        if \"error\" in step_result:\n            print(f\"❌ 步骤 {step_count + 1} 执行失败: {step_result['error']}\")\n            break\n        \n        if step_result.get(\"status\") == \"demo_completed\":\n            print(f\"✅ 演示完成\")\n            print(f\"   总时长: {step_result['total_duration']:.1f}秒\")\n            print(f\"   完成步骤: {step_result['completed_steps']}\")\n            break\n        else:\n            step_count += 1\n            print(f\"✅ 步骤 {step_count} 完成: {step_result['step_completed']}\")\n            print(f\"   进度: {step_result['progress']['percentage']:.1f}%\")\n    \n    # 4. 测试演示状态\n    print(\"\\n📊 测试演示状态\")\n    status = demo_flow.get_current_demo_status()\n    if status:\n        print(f\"✅ 获取状态成功\")\n        print(f\"   当前步骤: {status['current_step']}/{status['total_steps']}\")\n        print(f\"   进度: {status['progress_percentage']:.1f}%\")\n    else:\n        print(f\"ℹ️ 无活跃演示（可能已完成）\")\n    \n    # 5. 测试演示历史\n    print(\"\\n📚 测试演示历史\")\n    history = demo_flow.get_demo_history()\n    print(f\"✅ 获取历史记录: {len(history)} 条\")\n    \n    for i, record in enumerate(history, 1):\n        print(f\"   {i}. {record['scenario_name']} - {record['status']}\")\n    \n    print(\"\\n🎉 交互式演示流程测试完成！\")\n    return True\n\n\nif __name__ == \"__main__\":\n    try:\n        success = asyncio.run(test_demo_flow())\n        print(f\"\\n测试结果: {'成功' if success else '失败'}\")\n    except Exception as e:\n        print(f\"\\n❌ 测试过程中发生错误: {e}\")\n        import traceback\n        traceback.print_exc()\n"